package com.casegen.generation.backend;
import static org.junit.jupiter.api.Assertions.*;
import com.casegen.auth.domain.User;import com.casegen.auth.repository.UserRepository;import com.casegen.generation.backend.service.*;import com.casegen.generation.dto.*;import com.casegen.generation.logical.service.LogicalModelService;import com.casegen.generation.service.GenerationProfileService;import com.casegen.modeling.command.*;import com.casegen.modeling.domain.*;import com.casegen.modeling.service.UmlModelService;import com.casegen.modeling.service.UmlRelationshipService;import com.casegen.project.domain.*;import com.casegen.project.repository.*;import com.casegen.validation.service.ValidationService;import com.casegen.versioning.service.ModelVersionService;
import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.TimeUnit;import java.util.zip.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.junit.jupiter.api.io.TempDir;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.test.context.TestConstructor;import tools.jackson.databind.json.JsonMapper;
@SpringBootTest @EnabledIfEnvironmentVariable(named="DB_URL",matches="jdbc:postgresql:.*") @TestConstructor(autowireMode=TestConstructor.AutowireMode.ALL)
class GenerationBackendIntegrationTest {
 private final UserRepository users;private final ProjectRepository projects;private final ProjectMemberRepository members;private final UmlModelService models;private final UmlRelationshipService relationships;private final ValidationService validation;private final ModelVersionService versions;private final GenerationProfileService profiles;private final LogicalModelService logical;private final GenerationService generation;private final SpringBackendRenderer renderer;private final IsolatedPostgresVerifier postgres;private final JsonMapper json=JsonMapper.builder().build();
 GenerationBackendIntegrationTest(UserRepository users,ProjectRepository projects,ProjectMemberRepository members,UmlModelService models,UmlRelationshipService relationships,ValidationService validation,ModelVersionService versions,GenerationProfileService profiles,LogicalModelService logical,GenerationService generation,SpringBackendRenderer renderer,IsolatedPostgresVerifier postgres){this.users=users;this.projects=projects;this.members=members;this.models=models;this.relationships=relationships;this.validation=validation;this.versions=versions;this.profiles=profiles;this.logical=logical;this.generation=generation;this.renderer=renderer;this.postgres=postgres;}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void customerBackendCompilesMigratesValidatesAndPackagesInSeparateWorkspace()throws Exception{
  User owner=account("Owner");Project project=projects.saveAndFlush(new Project("V10 "+UUID.randomUUID(),null));members.saveAndFlush(new ProjectMember(project,owner,ProjectMemberRole.OWNER));authenticate(owner);
  UUID model=models.createModel(project.getId(),new CreateUmlModelCommand("Customer model",null)).id();UUID customer=models.createClassifier(model,new CreateUmlClassifierCommand("Customer",null,null,ClassifierKind.CLASS,Visibility.PUBLIC,false,false)).id();
  UUID id=models.createProperty(model,customer,new CreateUmlPropertyCommand("id",null,Visibility.PRIVATE,TypeKind.PRIMITIVE,PrimitiveType.STRING,null,1,1,false,false,false)).id();
  models.createProperty(model,customer,new CreateUmlPropertyCommand("email",null,Visibility.PRIVATE,TypeKind.PRIMITIVE,PrimitiveType.STRING,null,0,1,false,false,false));
  UUID sale=models.createClassifier(model,new CreateUmlClassifierCommand("Sale",null,null,ClassifierKind.CLASS,Visibility.PUBLIC,false,false)).id();UUID saleId=models.createProperty(model,sale,new CreateUmlPropertyCommand("id",null,Visibility.PRIVATE,TypeKind.PRIMITIVE,PrimitiveType.STRING,null,1,1,false,false,false)).id();
  relationships.createAssociation(model,new CreateUmlAssociationCommand(null,null,null,new UmlAssociationEndCommand("customer",customer,Visibility.PUBLIC,1,1,false,AggregationKind.NONE,AssociationEndOwnership.ASSOCIATION),new UmlAssociationEndCommand("sales",sale,Visibility.PUBLIC,0,null,false,AggregationKind.NONE,AssociationEndOwnership.ASSOCIATION)));
  UUID product=models.createClassifier(model,new CreateUmlClassifierCommand("Product",null,null,ClassifierKind.CLASS,Visibility.PUBLIC,false,false)).id();UUID productId=models.createProperty(model,product,new CreateUmlPropertyCommand("id",null,Visibility.PRIVATE,TypeKind.PRIMITIVE,PrimitiveType.STRING,null,1,1,false,false,false)).id();
  UUID category=models.createClassifier(model,new CreateUmlClassifierCommand("Category",null,null,ClassifierKind.CLASS,Visibility.PUBLIC,false,false)).id();UUID categoryId=models.createProperty(model,category,new CreateUmlPropertyCommand("id",null,Visibility.PRIVATE,TypeKind.PRIMITIVE,PrimitiveType.STRING,null,1,1,false,false,false)).id();
  relationships.createAssociation(model,new CreateUmlAssociationCommand(null,null,null,new UmlAssociationEndCommand("products",product,Visibility.PUBLIC,0,null,true,AggregationKind.NONE,AssociationEndOwnership.ASSOCIATION),new UmlAssociationEndCommand("categories",category,Visibility.PUBLIC,0,null,true,AggregationKind.NONE,AssociationEndOwnership.ASSOCIATION)));
  var profile=profiles.save(model,null,new GenerationProfileRequest("Backend",GenerationProfileRequest.Target.SPRING_BOOT,"com.test","customer-api","com.test.customer",21,"4.1.1",GenerationProfileRequest.Database.POSTGRESQL,null));
  profiles.saveMapping(model,profile.id(),null,new ElementMappingRequest(customer,ElementMappingRequest.TargetKind.ENTITY,json.valueToTree(Map.of("idPropertyId",id.toString()))));
  profiles.saveMapping(model,profile.id(),null,new ElementMappingRequest(sale,ElementMappingRequest.TargetKind.ENTITY,json.valueToTree(Map.of("idPropertyId",saleId.toString()))));
  profiles.saveMapping(model,profile.id(),null,new ElementMappingRequest(product,ElementMappingRequest.TargetKind.ENTITY,json.valueToTree(Map.of("idPropertyId",productId.toString()))));
  profiles.saveMapping(model,profile.id(),null,new ElementMappingRequest(category,ElementMappingRequest.TargetKind.ENTITY,json.valueToTree(Map.of("idPropertyId",categoryId.toString()))));
  assertEquals("VALID",validation.validate(model).status());var version=versions.create(model);var logicalModel=logical.build(version.id(),profile.id());assertEquals("VALID",logicalModel.status());
  long started=System.nanoTime();var accepted=generation.generate(logicalModel.id());assertEquals("QUEUED",accepted.status());assertTrue(Duration.ofNanos(System.nanoTime()-started).compareTo(Duration.ofSeconds(2))<0);
  var run=await(accepted.generationId());assertEquals("SUCCESS",run.status(),run.errorMessage());assertEquals("COMPLETED",run.currentStage());assertEquals(List.of("GENERATING","COMPILING","TESTING","VERIFYING_DATABASE","PACKAGING"),run.tests().stream().map(t->t.testType()).toList());assertTrue(run.tests().stream().allMatch(t->t.status().equals("SUCCESS")));assertEquals(1,run.artifacts().size());assertEquals("customer-api-v1.zip",run.artifacts().getFirst().fileName());
  var firstDownload=generation.download(run.id(),run.artifacts().getFirst().id());Set<String>zip=entries(firstDownload);assertTrue(zip.contains("customer-api/pom.xml"));assertTrue(zip.contains("customer-api/mvnw"));assertTrue(zip.contains("customer-api/mvnw.cmd"));assertTrue(zip.contains("customer-api/.env"));assertTrue(zip.contains("customer-api/.env.example"));assertTrue(zip.contains("customer-api/.gitignore"));assertTrue(zip.contains("customer-api/run.ps1"));assertTrue(zip.contains("customer-api/run.sh"));assertTrue(zip.contains("customer-api/Dockerfile"));assertTrue(zip.contains("customer-api/README.md"));assertTrue(zip.contains("customer-api/postman/customer-api.postman_collection.json"));assertTrue(zip.contains("customer-api/src/main/resources/db/migration/V1__create_schema.sql"));assertTrue(zip.stream().noneMatch(e->e.contains("/target/")||e.contains("/runtime/")||e.contains("/.git/")));
  User collaborator=account("Collaborator");members.saveAndFlush(new ProjectMember(project,collaborator,ProjectMemberRole.COLLABORATOR));authenticate(collaborator);
  var secondAccepted=generation.generate(logicalModel.id());var second=await(secondAccepted.generationId());assertEquals("SUCCESS",second.status(),second.errorMessage());assertNotEquals(run.id(),second.id());assertEquals(run.artifacts().getFirst().checksum(),second.artifacts().getFirst().checksum());assertEquals(List.of(second.id(),run.id()),generation.history(logicalModel.id()).stream().limit(2).map(r->r.id()).toList());var secondDownload=generation.download(second.id(),second.artifacts().getFirst().id());assertNotEquals(firstDownload.resource().getFile(),secondDownload.resource().getFile());
  User viewer=account("Viewer");members.saveAndFlush(new ProjectMember(project,viewer,ProjectMemberRole.VIEWER));authenticate(viewer);assertThrows(org.springframework.security.access.AccessDeniedException.class,()->generation.generate(logicalModel.id()));assertThrows(org.springframework.security.access.AccessDeniedException.class,()->generation.download(run.id(),run.artifacts().getFirst().id()));
 }
 @Test void associationEntityWithBusinessColumnCompilesAndValidatesJpa(@TempDir Path workspace)throws Exception{
  var profile=json.valueToTree(Map.of("profile",Map.of("basePackage","com.test.association","artifactId","association-api","groupId","com.test","javaVersion",21,"springBootVersion","4.1.1")));
  var product=logicalEntity("product");var category=logicalEntity("category");
  var bridge=new com.casegen.generation.logical.dto.LogicalModelDtos.Table("product_category",null,UUID.randomUUID().toString(),List.of(
          new com.casegen.generation.logical.dto.LogicalModelDtos.Column("product_id",null,"UUID",false,1),
          new com.casegen.generation.logical.dto.LogicalModelDtos.Column("category_id",null,"UUID",false,2),
          new com.casegen.generation.logical.dto.LogicalModelDtos.Column("assigned_at",null,"VARCHAR(255)",false,3)),
          new com.casegen.generation.logical.dto.LogicalModelDtos.Key("pk_product_category",List.of("product_id","category_id"),null),List.of(
          new com.casegen.generation.logical.dto.LogicalModelDtos.ForeignKey("fk_pc_product","product",List.of(new com.casegen.generation.logical.dto.LogicalModelDtos.ColumnPair("product_id","id")),"CASCADE",null),
          new com.casegen.generation.logical.dto.LogicalModelDtos.ForeignKey("fk_pc_category","category",List.of(new com.casegen.generation.logical.dto.LogicalModelDtos.ColumnPair("category_id","id")),"CASCADE",null)),List.of(),List.of(),List.of());
  var input=new com.casegen.generation.logical.dto.LogicalModelDtos.Response(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),profile,"VALID","checksum",UUID.randomUUID(),Instant.now(),List.of(product,category,bridge),List.of());
  renderer.render(workspace,input,new SpringBackendRenderer.Traceability(UUID.randomUUID(),UUID.randomUUID(),"Association",input.modelVersionId(),1,input.id()));
  assertTrue(Files.readString(workspace.resolve("src/main/java/com/test/association/repository/ProductCategoryRepository.java")).contains("JpaRepository<ProductCategory,ProductCategoryId>"));
  UUID run=UUID.randomUUID();var database=postgres.create(run);try{ProcessBuilder builder=new ProcessBuilder("mvnw.cmd","test").directory(workspace.toFile()).redirectErrorStream(true);builder.environment().putAll(database.environment());Process process=builder.start();String output=new String(process.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);assertTrue(process.waitFor(5,TimeUnit.MINUTES),"Generated Maven test timed out");assertEquals(0,process.exitValue(),output);}finally{postgres.remove(database);}
 }
 private com.casegen.generation.logical.dto.LogicalModelDtos.Table logicalEntity(String name){return new com.casegen.generation.logical.dto.LogicalModelDtos.Table(name,UUID.randomUUID().toString(),null,List.of(new com.casegen.generation.logical.dto.LogicalModelDtos.Column("id",UUID.randomUUID().toString(),"UUID",false,1)),new com.casegen.generation.logical.dto.LogicalModelDtos.Key("pk_"+name,List.of("id"),null),List.of(),List.of(),List.of(),List.of());}
 private Set<String> entries(GenerationService.ArtifactDownload download)throws Exception{Set<String>names=new HashSet<>();try(var zip=new ZipInputStream(download.resource().getInputStream())){for(ZipEntry entry;(entry=zip.getNextEntry())!=null;)names.add(entry.getName());}return names;}
 private com.casegen.generation.backend.dto.GenerationDtos.Response await(UUID id){Instant deadline=Instant.now().plus(Duration.ofMinutes(5));while(Instant.now().isBefore(deadline)){var run=generation.get(id);if(run.status().equals("SUCCESS")||run.status().equals("FAILED"))return run;try{Thread.sleep(250);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new AssertionError(e);}}throw new AssertionError("Generation did not finish: "+id);}
 private User account(String name){return users.saveAndFlush(new User(UUID.randomUUID()+"@test.local","hashed",name));}private void authenticate(User user){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(user.getId().toString(),"",List.of()));}
}
